/**
 * @summary Get all feedback (optionally filtered by analysis)
 */
export const getGetFeedbackListUrl = (params?: GetFeedbackListParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/feedback?${stringifiedParams}`
    : `/api/feedback`;
};

export const getFeedbackList = async (
  params?: GetFeedbackListParams,
  options?: RequestInit,
): Promise<FeedbackListResponse> => {
  return customFetch<FeedbackListResponse>(getGetFeedbackListUrl(params), {
    ...options,
    method: "GET",
  });
};

